 auto refuse=[&](const seed::Result&r,bool attempted){bool denied=false;try{codec::validate(r,attempted);}catch(const std::invalid_argument&){denied=true;}need(denied,"malformed initializer record refused before write");};auto malformed=flat;malformed.retry_available=false;refuse(malformed,true);malformed=flat;malformed.error="outer failure after retry success";malformed.complete=false;codec::validate(malformed,true);malformed.complete=true;refuse(malformed,true);malformed=flat;malformed.retry.changed=true;refuse(malformed,true);malformed=flat;malformed.corrections[0].delta(0)=1e-20;refuse(malformed,true);malformed=maximum;malformed.retry.row_bounds_written=20001;refuse(malformed,true);malformed=maximum;malformed.corrections.push_back({});refuse(malformed,true);malformed=maximum;malformed.error.push_back('x');refuse(malformed,true);malformed=flat;malformed.corrections[0].eligibility_reason=2;refuse(malformed,true);malformed=flat;malformed.corrections[0].required_domain_improvement=0;refuse(malformed,true);malformed=flat;malformed.corrections[0].after_available=false;refuse(malformed,true);malformed=flat;malformed.corrector_scope_entered=false;refuse(malformed,true);
